import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3]  # House indices 1..3
    # Attributes
    Names = ['Eric', 'Peter', 'Arnold']
    Drinks = ['tea', 'water', 'milk']
    Nationalities = ['dane', 'brit', 'swede']
    Educations = ['high school', 'associate', 'bachelor']
    HouseStyles = ['victorian', 'colonial', 'ranch']
    Smoothies = ['cherry', 'watermelon', 'desert']

    solutions = []

    # Helper to get index of a value in a list
    def pos(lst, value):
        return lst.index(value)

    for names in permutations(Names):
        # Clue 1 implies Eric must be at one of the ends; otherwise impossible with 3 houses
        if pos(names, 'Eric') == 1:
            continue  # Eric cannot be in the middle with "one house between"

        for styles in permutations(HouseStyles):
            # Clue 6: Victorian not in the first house
            if styles[0] == 'victorian':
                continue
            # Clue 8: Arnold is somewhere to the right of the person residing in a Victorian house
            if not (pos(names, 'Arnold') > pos(styles, 'victorian')):
                continue

            for drinks in permutations(Drinks):
                # Clue 1: There is one house between Eric and the tea drinker
                if abs(pos(names, 'Eric') - pos(drinks, 'tea')) != 2:
                    continue

                for educations in permutations(Educations):
                    # Clue 3: The person with a bachelor's degree is in the second house
                    if educations[1] != 'bachelor':
                        continue

                    # Clue 9: Ranch-style home <-> High school diploma
                    if pos(styles, 'ranch') != pos(educations, 'high school'):
                        continue

                    # Clue 2: Milk <-> Ranch-style home
                    if pos(drinks, 'milk') != pos(styles, 'ranch'):
                        continue

                    for nationalities in permutations(Nationalities):
                        # Clue 4: High school diploma holder is the Dane
                        if pos(educations, 'high school') != pos(nationalities, 'dane'):
                            continue

                        for smoothies in permutations(Smoothies):
                            # Clue 5: Desert smoothie lover is the Swede
                            if pos(smoothies, 'desert') != pos(nationalities, 'swede'):
                                continue

                            # Clue 7: Cherry smoothie <-> Colonial house
                            if pos(smoothies, 'cherry') != pos(styles, 'colonial'):
                                continue

                            # All constraints satisfied; record solution
                            solution = {
                                "names": names,
                                "drinks": drinks,
                                "nationalities": nationalities,
                                "educations": educations,
                                "styles": styles,
                                "smoothies": smoothies
                            }
                            solutions.append(solution)

    if not solutions:
        raise RuntimeError("No solution found")

    # Assuming unique solution; take the first
    sol = solutions[0]

    header = ["House", "Name", "Drink", "Nationality", "Education", "HouseStyle", "Smoothie"]
    rows = []
    for i in range(3):
        row = [
            str(i + 1),
            sol["names"][i],
            sol["drinks"][i],
            sol["nationalities"][i],
            sol["educations"][i],
            sol["styles"][i],
            sol["smoothies"][i]
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
